// Shop interiors, shopkeepers and display furniture. Rows are generated by small helpers.
const mk = (w, h, c = '.') => Array.from({ length: h }, () => Array(w).fill(c));
const px = (g, x, y, c) => { if (y >= 0 && y < g.length && x >= 0 && x < g[0].length) g[y][x] = c; };
const rect = (g, x, y, w, h, c) => { for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) px(g, x + i, y + j, c); };
const disc = (g, cx, cy, r, c) => { for (let j = -r; j <= r; j++) for (let i = -r; i <= r; i++) if (i * i + j * j <= r * r + r / 2) px(g, cx + i, cy + j, c); };
const stamp = (g, s, x, y) => s.rows.forEach((row, j) => { for (let i = 0; i < row.length; i++) if (row[i] !== '.') px(g, x + i, y + j, row[i]); });
const rows = (g) => g.map((r) => r.join(''));
const spr = (g) => ({ w: g[0].length, h: g.length, rows: rows(g) });
const outl = (g) => {
  const h = g.length, w = g[0].length;
  const add = [];
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    if (g[y][x] !== '.') continue;
    if ([[1, 0], [-1, 0], [0, 1], [0, -1]].some(([a, b]) => g[y + b] && g[y + b][x + a] && g[y + b][x + a] !== '.' && g[y + b][x + a] !== 'O')) add.push([x, y]);
  }
  add.forEach(([x, y]) => { g[y][x] = 'O'; });
  return g;
};

// Display sprites
const rack = () => {
  const g = mk(16, 16);
  rect(g, 1, 3, 14, 1, 'd');
  rect(g, 1, 4, 1, 11, 'd'); rect(g, 14, 4, 1, 11, 'd');
  rect(g, 0, 14, 3, 1, 'e'); rect(g, 13, 14, 3, 1, 'e');
  [['n', 2], ['u', 5], ['h', 8], ['q', 11]].forEach(([c, x]) => {
    px(g, x + 1, 4, 'f'); rect(g, x, 5, 3, 1, c); rect(g, x, 6, 3, 6, c); rect(g, x + 2, 6, 1, 6, 'W');
  });
  rect(g, 2, 4, 12, 1, 'd');
  return spr(outl(g));
};
const stand = () => {
  const g = mk(16, 24);
  disc(g, 8, 4, 3, 'b');
  rect(g, 7, 7, 2, 2, 'b');
  rect(g, 4, 9, 8, 7, 'n'); rect(g, 10, 9, 2, 7, 'o'); rect(g, 3, 9, 1, 3, 'b'); rect(g, 12, 9, 1, 3, 'b');
  rect(g, 5, 16, 6, 3, 'u'); rect(g, 9, 16, 2, 3, 'v');
  rect(g, 7, 19, 2, 3, 'd');
  rect(g, 4, 22, 8, 1, 'e');
  return spr(outl(g));
};
const mirror = () => {
  const g = mk(16, 24);
  rect(g, 2, 1, 12, 18, 'd');
  rect(g, 3, 2, 10, 16, 's');
  rect(g, 4, 3, 2, 6, 'W'); rect(g, 7, 12, 4, 1, 't'); rect(g, 6, 7, 3, 1, 't');
  rect(g, 3, 14, 10, 4, 't');
  rect(g, 7, 19, 2, 3, 'e'); rect(g, 4, 22, 8, 1, 'e'); rect(g, 3, 23, 10, 1, 'd');
  return spr(outl(g));
};
const shelf = () => {
  const g = mk(16, 16);
  rect(g, 1, 1, 14, 14, 'c'); rect(g, 2, 2, 12, 5, 'e'); rect(g, 2, 9, 12, 5, 'e');
  rect(g, 1, 7, 14, 2, 'd');
  rect(g, 3, 4, 3, 3, 'n'); rect(g, 8, 3, 2, 4, 'u'); rect(g, 11, 5, 2, 2, 'h');
  rect(g, 3, 11, 4, 3, 'W'); rect(g, 9, 10, 3, 4, 'p');
  return spr(outl(g));
};
const dcase = () => {
  const g = mk(32, 16);
  rect(g, 1, 1, 30, 14, 'd');
  rect(g, 2, 2, 28, 9, 's'); rect(g, 3, 3, 3, 2, 'W');
  [['m', 4], ['b', 11], ['o', 18], ['a', 24]].forEach(([c, x]) => { rect(g, x, 6, 5, 4, c); rect(g, x, 5, 5, 1, 'W'); px(g, x + 2, 4, 'p'); });
  rect(g, 2, 11, 28, 1, 'W');
  rect(g, 2, 12, 28, 3, 'c');
  return spr(outl(g));
};
const counter = () => {
  const g = mk(32, 16);
  rect(g, 0, 2, 32, 4, 'c'); rect(g, 0, 2, 32, 1, 'b');
  rect(g, 1, 6, 30, 9, 'd');
  for (let x = 3; x < 30; x += 7) rect(g, x, 8, 5, 5, 'e');
  rect(g, 4, 0, 6, 2, 'W'); rect(g, 4, 0, 6, 1, 's');
  rect(g, 22, 0, 5, 2, 'n');
  return spr(outl(g));
};
const D = { rack: rack(), stand: stand(), mirror: mirror(), shelf: shelf(), case: dcase(), counter: counter() };

// Tiles
const woodFloor = () => {
  const g = mk(16, 16, 'c');
  for (let y = 0; y < 16; y += 4) { rect(g, 0, y + 3, 16, 1, 'd'); rect(g, (y * 3 + 5) % 16, y, 1, 3, 'd'); rect(g, (y * 5 + 2) % 16, y + 1, 3, 1, 'b'); }
  return g;
};
const checkFloor = (a, b) => {
  const g = mk(16, 16, a);
  rect(g, 8, 0, 8, 8, b); rect(g, 0, 8, 8, 8, b);
  return g;
};
const wallTile = (a, b, c) => {
  const g = mk(16, 16, a);
  rect(g, 0, 0, 1, 16, b); rect(g, 8, 0, 1, 16, b);
  rect(g, 4, 5, 1, 1, c); rect(g, 12, 11, 1, 1, c);
  return g;
};
const tiled = (g, t, x0, y0, tw, th) => {
  for (let j = 0; j < th; j++) for (let i = 0; i < tw; i++) stamp(g, { rows: rows(t) }, x0 + i * 16, y0 + j * 16);
};
const base = (wallT, floorT, wallRows) => {
  const g = mk(320, 224);
  tiled(g, wallT, 0, 0, 20, wallRows);
  tiled(g, floorT, 0, wallRows * 16, 20, 14 - wallRows);
  const wy = wallRows * 16;
  rect(g, 0, wy - 4, 320, 4, 'W'); rect(g, 0, wy - 5, 320, 1, 'b');
  rect(g, 0, 0, 320, 3, 'd');
  rect(g, 0, wy, 320, 2, 'e');
  return g;
};
const mat = (g, x, y) => { rect(g, x, y, 32, 16, 'p'); rect(g, x + 2, y + 2, 28, 12, 'n'); rect(g, x + 4, y + 4, 24, 8, 'm'); };

const boutique = () => {
  const g = base(wallTile('m', 'n', 'W'), woodFloor(), 5);
  [16, 48, 80, 112].forEach((x) => stamp(g, D.rack, x, 62));
  stamp(g, D.stand, 160, 56); stamp(g, D.stand, 182, 56);
  stamp(g, D.mirror, 214, 52);
  stamp(g, D.counter, 256, 66); stamp(g, D.counter, 288, 66);
  [[40, 120], [120, 120], [200, 120], [80, 168], [160, 168]].forEach(([x, y]) => stamp(g, D.rack, x, y));
  stamp(g, D.stand, 270, 130);
  stamp(g, D.mirror, 20, 20 + 0);
  mat(g, 144, 208);
  return g;
};
const lamp = (g, x, y) => { rect(g, x + 2, y, 8, 5, 'W'); rect(g, x + 3, y + 1, 6, 3, 'b'); rect(g, x + 5, y + 5, 2, 8, 'e'); rect(g, x + 2, y + 13, 8, 2, 'd'); };
const chair = (g, x, y) => { rect(g, x, y, 10, 10, 'd'); rect(g, x + 1, y + 1, 8, 4, 'o'); rect(g, x + 1, y + 5, 8, 4, 'p'); rect(g, x, y + 10, 2, 5, 'e'); rect(g, x + 8, y + 10, 2, 5, 'e'); };
const rug = (g, x, y, w, h, a, b) => { rect(g, x, y, w, h, a); rect(g, x + 2, y + 2, w - 4, h - 4, b); rect(g, x + 4, y + 4, w - 8, h - 8, a); };
const home = () => {
  const g = base(wallTile('g', 'h', 'W'), woodFloor(), 5);
  stamp(g, D.shelf, 16, 62); stamp(g, D.shelf, 48, 62);
  lamp(g, 100, 54); lamp(g, 140, 54); lamp(g, 180, 54);
  stamp(g, D.shelf, 216, 62);
  stamp(g, D.counter, 256, 66); stamp(g, D.counter, 288, 66);
  rug(g, 32, 112, 80, 48, 'q', 'n'); rug(g, 140, 120, 64, 40, 'u', 's'); rug(g, 230, 130, 56, 40, 'j', 'g');
  chair(g, 60, 128); chair(g, 160, 132); chair(g, 248, 144); chair(g, 36, 176); chair(g, 100, 176);
  lamp(g, 220, 176); lamp(g, 290, 176);
  mat(g, 144, 208);
  return g;
};
const cafe = (g, x, y) => {
  rect(g, x + 6, y + 8, 2, 7, 'e'); rect(g, x + 3, y + 14, 8, 1, 'e');
  disc(g, x + 7, y + 7, 5, 'W'); rect(g, x + 3, y + 5, 8, 3, 'a');
  rect(g, x - 2, y + 4, 3, 10, 'd'); rect(g, x - 4, y + 4, 2, 5, 'o');
  rect(g, x + 13, y + 4, 3, 10, 'd'); rect(g, x + 16, y + 4, 2, 5, 'o');
};
const bakery = () => {
  const g = base(wallTile('a', 'b', 'n'), checkFloor('W', 'm'), 5);
  stamp(g, D.case, 150, 62); stamp(g, D.case, 182, 62);
  stamp(g, D.counter, 214, 66);
  stamp(g, D.shelf, 16, 62);
  // oven
  rect(g, 60, 36, 40, 44, 'f'); rect(g, 62, 38, 36, 40, 'e'); rect(g, 66, 46, 28, 22, 'o'); rect(g, 68, 48, 24, 18, 'c');
  rect(g, 72, 52, 5, 4, 'b'); rect(g, 82, 54, 6, 4, 'b'); rect(g, 64, 40, 3, 3, 'W'); rect(g, 70, 40, 3, 3, 'W'); rect(g, 60, 70, 40, 2, 'd');
  stamp(g, D.counter, 256, 66); stamp(g, D.counter, 288, 66);
  cafe(g, 36, 112); cafe(g, 116, 112); cafe(g, 36, 160); cafe(g, 116, 160);
  mat(g, 144, 208);
  return g;
};

const tilePair = (id, wt, ft, room) => ({
  [`shop.${id}.floor`]: spr(ft), [`shop.${id}.wall`]: spr(wt), [`shop.${id}.room`]: spr(room),
});

// Shopkeepers
const keeper = (kind, frame, wave) => {
  const g = mk(16, 24);
  const oy = !wave && frame === 1 ? 1 : 0;
  const Y = (y) => y + oy;
  rect(g, 4, Y(3), 8, 4, '4');
  rect(g, 4, Y(7), 8, 1, '5');
  if (kind === 'boutique') { rect(g, 3, Y(5), 1, 6, '4'); rect(g, 12, Y(5), 1, 6, '4'); rect(g, 10, Y(3), 2, 1, 'n'); }
  rect(g, 4, Y(8), 8, 4, '1');
  px(g, 6, Y(9), 'E'); px(g, 9, Y(9), 'E'); px(g, 5, Y(10), 'B'); px(g, 10, Y(10), 'B');
  px(g, 7, Y(11), '2'); px(g, 8, Y(11), '2');
  if (kind === 'home') { rect(g, 5, Y(9), 3, 1, 'w'); rect(g, 8, Y(9), 3, 1, 'w'); px(g, 6, Y(9), 'E'); px(g, 9, Y(9), 'E'); }
  if (kind === 'bakery') { rect(g, 5, Y(1), 6, 2, 'W'); rect(g, 4, Y(3), 8, 1, 'W'); rect(g, 4, Y(2), 1, 1, 'W'); px(g, 11, Y(2), '.'); rect(g, 11, Y(2), 1, 1, 'W'); }
  const oc = kind === 'boutique' ? ['7', '8'] : kind === 'home' ? ['h', 'i'] : ['o', 'p'];
  rect(g, 4, Y(12), 8, 7, oc[0]); rect(g, 10, Y(12), 2, 7, oc[1]);
  if (kind === 'home') { rect(g, 6, Y(14), 4, 3, 'e'); }
  if (kind === 'bakery') { rect(g, 5, Y(14), 6, 5, 'W'); rect(g, 10, Y(14), 1, 5, 's'); }
  if (kind === 'boutique') { rect(g, 4, Y(12), 8, 1, 'W'); }
  rect(g, 3, Y(13), 1, 5, '2');
  if (wave) {
    const up = frame === 1 ? 1 : 0;
    rect(g, 12, Y(7) + up, 1, 6, '2'); rect(g, 13 - up * 0, Y(6) + up, 1, 2, '1');
    if (frame === 1) { rect(g, 13, Y(6) + 1, 1, 2, '1'); }
  } else rect(g, 12, Y(13), 1, 5, '2');
  rect(g, 5, Y(19), 2, 2, 'L'); rect(g, 9, Y(19), 2, 2, 'L');
  rect(g, 4, Y(21), 3, 1, 'e'); rect(g, 9, Y(21), 3, 1, 'e');
  return spr(outl(g));
};

const sprites = {};
const anims = {};
Object.assign(sprites, tilePair('boutique', wallTile('m', 'n', 'W'), woodFloor(), boutique()));
Object.assign(sprites, tilePair('home', wallTile('g', 'h', 'W'), woodFloor(), home()));
Object.assign(sprites, tilePair('bakery', wallTile('a', 'b', 'n'), checkFloor('W', 'm'), bakery()));
for (const k of Object.keys(D)) sprites[`display.${k}`] = D[k];
for (const k of ['boutique', 'home', 'bakery']) {
  [0, 1].forEach((f) => { sprites[`npc.${k}.idle.${f}`] = keeper(k, f, false); });
  [0, 1, 2].forEach((f) => { sprites[`npc.${k}.wave.${f}`] = keeper(k, f, true); });
  sprites[`npc.${k}`] = sprites[`npc.${k}.idle.0`];
  anims[`npc.${k}.idle`] = { id: `npc.${k}.idle`, frames: [`npc.${k}.idle.0`, `npc.${k}.idle.1`], fps: 2, loop: true };
  anims[`npc.${k}.wave`] = { id: `npc.${k}.wave`, frames: [`npc.${k}.wave.0`, `npc.${k}.wave.1`, `npc.${k}.wave.2`], fps: 4, loop: true };
}

export default { sprites, anims, meta: { shops: ['boutique', 'home', 'bakery'] } };
